#!/usr/bin/env python3
"""Builds the Extended edition next to the open one, locally: the same clean tree plus the account and paid connectors, with PSN_EDITION=extended. Not part of the contest entry. Nothing is pushed. Usage: assemble_extended.py [--open DIR] [--out DIR]"""
import argparse, os, shutil, subprocess
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."); ap = argparse.ArgumentParser(); ap.add_argument("--open", default=os.path.expanduser("~/public_release/ComfyUI_Parametric_Studio")); ap.add_argument("--out", default=os.path.expanduser("~/public_release/ComfyUI_Parametric_Studio_Extended")); a = ap.parse_args()
if not os.path.isdir(a.open): raise SystemExit("Build the open tree first: scripts/assemble_public.py")
shutil.rmtree(a.out, ignore_errors=True); shutil.copytree(a.open, a.out, ignore=shutil.ignore_patterns(".git")); shutil.copy(os.path.join(ROOT, "studio", "printify.py"), os.path.join(a.out, "studio", "printify.py"))
if os.path.isdir(os.path.join(ROOT, "extended_candidates")): shutil.copytree(os.path.join(ROOT, "extended_candidates"), os.path.join(a.out, "extended_candidates"), ignore=shutil.ignore_patterns("__pycache__"))
open(os.path.join(a.out, "extended.env"), "w").write("PSN_EDITION=extended\n# COMFY_API_KEY=comfyui-...   your own key: partner nodes spend your Comfy credits\n")
open(os.path.join(a.out, "README_EXTENDED.md"), "w").write("# Parametric Studio, Extended edition\n\nThe open studio plus paid and account connectors, all off until you add your own keys. Start it with `PSN_EDITION=extended` (see `extended.env`). You get ComfyUI's partner-node workflows as forms on the Apps page, which spend your Comfy credits, and Connect your Printify on the Designers page, which creates draft products only. It is not the contest entry and does not qualify for Open Weights Only.\n")
subprocess.run(["git", "init", "-q", "-b", "main", a.out], check=True); subprocess.run(["git", "-C", a.out, "add", "-A"], check=True); subprocess.run(["git", "-C", a.out, "-c", "user.name=Parametric Studio", "-c", "user.email=noreply@users.noreply.github.com", "commit", "-qm", "Parametric Studio, Extended edition"], check=True); print("extended tree:", a.out)
